ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  "error": {
    "code": "SHIPPING_BAD_REQUEST",
    "message": "Invalid request parameters",
    "correlationId": vars.correlationId,
    "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "SHIPPING_NOT_FOUND",
    "message": "Resource not found",
    "correlationId": vars.correlationId,
    "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "SHIPPING_INTERNAL_ERROR",
    "message": "Internal server error occurred",
    "correlationId": vars.correlationId,
    "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
  }
}

%dw 2.0
output application/json
---
{
  "orderReference": payload.orderId,
  "serviceType": payload.shippingMethod default "STANDARD",
  "recipient": {
    "name": payload.shippingAddress.fullName,
    "address": {
      "street": payload.shippingAddress.street,
      "city": payload.shippingAddress.city,
      "state": payload.shippingAddress.state,
      "postalCode": payload.shippingAddress.postalCode,
      "country": payload.shippingAddress.country
    },
    "phone": payload.shippingAddress.phone,
    "email": payload.shippingAddress.email
  },
  "items": payload.items map (item, index) -> {
    "description": item.name,
    "quantity": item.quantity,
    "weight": item.weight default 1.0,
    "value": item.price
  },
  "specialInstructions": payload.specialInstructions
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "SHIPPING_PROVIDER_UNAVAILABLE",
    "message": "Shipping service is temporarily unavailable",
    "correlationId": vars.correlationId,
    "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "SHIPPING_INVALID_REQUEST",
    "message": "Invalid shipping parameters provided",
    "correlationId": vars.correlationId,
    "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "SHIPMENT_NOT_FOUND",
    "message": "Shipment with ID " ++ vars.shipmentId ++ " not found",
    "correlationId": vars.correlationId,
    "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "SHIPPING_SERVICE_UNAVAILABLE",
    "message": "Tracking service is temporarily unavailable",
    "correlationId": vars.correlationId,
    "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
  }
}

%dw 2.0
output application/json
---
{
  (shipmentId: vars.shipmentId),
  (status: payload.status) if payload.status?,
  (deliveryInstructions: payload.deliveryInstructions) if payload.deliveryInstructions?,
  (destinationAddress: {
    street: payload.destinationAddress.street,
    city: payload.destinationAddress.city,
    state: payload.destinationAddress.state,
    zipCode: payload.destinationAddress.zipCode,
    country: payload.destinationAddress.country
  }) if payload.destinationAddress?,
  lastUpdated: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "SHIPMENT_NOT_FOUND",
    "message": "Shipment with ID " ++ vars.shipmentId ++ " not found for update",
    "correlationId": vars.correlationId,
    "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "SHIPPING_INVALID_UPDATE",
    "message": "Invalid update parameters provided for shipment",
    "correlationId": vars.correlationId,
    "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "SHIPPING_SERVICE_UNAVAILABLE",
    "message": "Shipping service is temporarily unavailable for updates",
    "correlationId": vars.correlationId,
    "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "SHIPMENT_NOT_FOUND",
    "message": "Shipment with ID " ++ vars.shipmentId ++ " not found for cancellation",
    "correlationId": vars.correlationId,
    "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "SHIPPING_SERVICE_UNAVAILABLE",
    "message": "Shipping service is temporarily unavailable for cancellation",
    "correlationId": vars.correlationId,
    "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
  }
}

%dw 2.0
output application/json
---
{
  "shipFrom": {
    "postalCode": payload.origin.zipCode,
    "country": payload.origin.country
  },
  "shipTo": {
    "postalCode": payload.destination.zipCode,
    "country": payload.destination.country
  },
  "packages": payload.packages map (pkg, index) -> {
    "weight": {
      "value": pkg.weight.value,
      "unit": pkg.weight.unit
    },
    "dimensions": {
      "length": pkg.dimensions.length,
      "width": pkg.dimensions.width,
      "height": pkg.dimensions.height,
      "unit": pkg.dimensions.unit
    }
  }
}

%dw 2.0
output application/json
---
{
  "rates": flatten(payload.* map (carrierResponse, index) -> 
    if (carrierResponse.error?)
      []
    else
      (carrierResponse.rates default []) map (rate, rateIndex) -> {
        "carrier": rate.carrier default "Unknown",
        "serviceType": rate.serviceType,
        "cost": rate.totalCost,
        "estimatedDays": rate.deliveryDays,
        "currency": rate.currency default "USD",
        "serviceDescription": rate.description default ""
      }
  ),
  "requestId": vars.correlationId,
  "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "SHIPPING_RATES_FAILED",
    "message": "Failed to retrieve shipping rates",
    "details": error.description,
    "correlationId": vars.correlationId,
    "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "TRACKING_NOT_FOUND",
    "message": "Tracking number " ++ vars.trackingNumber ++ " not found",
    "correlationId": vars.correlationId,
    "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "TRACKING_SERVICE_ERROR",
    "message": "Tracking service temporarily unavailable",
    "correlationId": vars.correlationId,
    "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
  }
}
